import ctypes

CMP = ctypes.CFUNCTYPE(ctypes.c_int, ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_int))
BINARY = ctypes.CFUNCTYPE(ctypes.c_int, ctypes.c_int, ctypes.c_int)


def make_comparator(key=None, reverse=False):
    def compare(a, b):
        x, y = a[0], b[0]
        if key is not None:
            x, y = key(x), key(y)
        result = (x > y) - (x < y)
        return -result if reverse else result
    return CMP(compare)


def _element(array, i):
    address = ctypes.addressof(array) + i * ctypes.sizeof(ctypes.c_int)
    return ctypes.cast(address, ctypes.POINTER(ctypes.c_int))


def c_style_sort(array, comparator):
    for i in range(1, len(array)):
        j = i
        while j > 0 and comparator(_element(array, j - 1), _element(array, j)) > 0:
            array[j - 1], array[j] = array[j], array[j - 1]
            j -= 1


class CallbackRegistry:
    def __init__(self):
        self.errors = []
        self._callbacks = {}

    def register(self, name, func):
        def safe(a, b):
            try:
                return func(a, b)
            except Exception as e:
                self.errors.append(e)
                return 0
        callback = BINARY(safe)
        self._callbacks[name] = callback
        return ctypes.cast(callback, ctypes.c_void_p).value

    def unregister(self, name):
        return self._callbacks.pop(name, None) is not None

    def call(self, address, a, b):
        return BINARY(address)(a, b)
